  LanguageConfig_2ndAnniversaryText_CN = {
    Text = "あなたがどこにいようとも、%player%。\nミサゴはずっと次元リンクを試みているの。きっと私たちはすぐにまた会えるかもしれない。\nドールが、あなたのいる次元を特定できたと言っていた。その知らせがどれほど嬉しかったか、言葉では言い表せないわ。\n私は普段、明確で正確、そして規則正しいものを好むけれど、このことに関しては、どんなにかすかで現実離れした希望であってもかまわない。\nどれだけ長く待つことになっても、永遠に再会できない別れなど、私には想像できない。\nもし今回うまくいかなくても大丈夫。次、その次、あるいは何千回でも、何度でも、私とミサゴの皆で、必ずあなたを連れ戻す。\b今は別々の次元にいても、ミサゴはシルバーコアテクノロジーを使って、あなたを助けるための方法を探しているわ。どうか、私たちの過去の記憶を集め、新たな記憶を紡いで、この贈り物をあなたの助けにしてほしい。\n私たちは皆、あなたが必ず戻ってくると信じている。\n私は、待つことが得意なのよ。"
