  LanguageConfig_AbyssChallengeTipsV2_CN = {
    Text = "<Title:「融災禁域」>\n·融災禁域は難易度の高いゲームプレイシステムです。シークレットキーパーは複数の挑戦チームを柔軟に組み合わせ、できるだけ多くの特訓値を獲得して、より多くの報酬を手に入れましょう。\n\n<Title:「禁域基本ルール」>\n·融災禁域は全5ウェーブで構成されており、各ウェーブには難易度の異なるステージが含まれています。\n·ステージをクリアすると、対応する数の特訓値を獲得できます。詳細はステージ詳細画面でご確認ください。\n·特訓値が指定の条件に達すると、「シルバーコア」と「黒い供物」に加え、貴重な物資「原初の霊核」「純粋な原初の霊核」も獲得できます！これはミサゴの地底ブラックプールで産出される神秘的な霊核で、覚醒体のレベル上限を引き上げ、最大90レベルまで上昇させることができます！\n·「融災禁域」は定期的にステージ内容と報酬が更新され、通常14日ごとに更新されます。当期の期間終了後、前期でまだ進行中の挑戦は即座に終了し、未受取の報酬は獲得できなくなります。シークレットキーパーは忘れずに期限内に完了・受取を行ってください～\n\n<Title:「禁域特殊ルール」>\n·融災禁域には独自の制限法則があります：同一の覚醒体とキーオーダー、同名の命輪は重複して出場できません。シークレットキーパーは初期遺物、モンスター、推奨レベルに応じて、今回の挑戦チームを柔軟に選択できます。\n·挑戦完了後、より良い組み合わせがあると発見した場合、「リセット」機能を使って対応するステージの挑戦チームをリセットできます。リセット後は覚醒体、キーオーダー、命輪を再び出場させることができますが、そのステージで獲得した特訓値も差し引かれます（報酬ステータスには影響しません）。\n·「融災禁域」では1回助っ人を使用できます。助っ人の覚醒体と命輪は制限法則の影響を受けません。助っ人覚醒体を含む挑戦チームをリセットした場合も、助っ人回数が1回返還されます。\n·挑戦中は「緊急れいち体」を使用してクリアを補助できます。使用のたびに「緊急れいち体」を3個消費します。使用後に完了した挑戦と特訓値は特別なマークが付き、特訓報酬は通常通り受け取れますが、ランキングには反映されません。\n\n<Title:「追加挑戦」>\n·いずれかのステージをクリアすると、そのステージの「追加挑戦」が解放され、より高い難易度の試練に挑めます。\n·追加挑戦は別途挑戦チームを編成する必要があり、同様に制限法則の影響を受けます：同一の覚醒体とキーオーダー、同名の命輪は重複して出場できません。助っ人回数は通常挑戦と共有されます（全プレイで計1回）。\n·追加挑戦をクリアすると特訓値5ポイントを獲得でき、当期の特訓値合計に加算されます。より多くの報酬の受取やランキング順位の上昇に役立ちます。\n·「リセット」機能を使って追加挑戦チームまたは通常挑戦チームを個別にリセットできます。\n·追加クリア後に通常挑戦チームをリセットした場合、追加挑戦チームは新しい通常挑戦チームに転換され、追加挑戦の進捗がリセットされ、追加クリアの特訓値も差し引かれます。\n\n<Title:「ランキング」>\n·現在、当期と前期の特訓値ランキング、および他のシークレットキーパーの融災禁域でのクリア情報を確認でき、シークレットキーパーへの参考情報として提供されます。\n·ランキングには当期の最高特訓値達成時の特訓値とクリア情報が表示されます。リセットはランキングやクリア編隊情報の表示に影響しません。\n·「緊急れいち体」を使用して挑戦をクリアした際に獲得した特訓値は特別なマークが付き、ランキングには反映されませんのでご注意ください。"
  },
  LanguageConfig_AbyssChallengeTips_CN = {
    Text = "<Title:「融災禁域」>\n·融災禁域は難易度の高いゲームプレイシステムです。シークレットキーパーは複数の挑戦編隊を柔軟に組み合わせ、できるだけ多くの特訓値を獲得し、より多くの報酬を手に入れましょう。\n\n<Title:「禁域基本ルール」>\n·融災禁域は合計5つのウェーブに分かれており、各ウェーブには難易度レベルの異なるステージが含まれています。\n·ステージをクリアすると、対応する数量の特訓値を獲得できます。詳細はステージ詳細画面で確認できます。\n·特訓値が指定の要件に達すると、「シルバーコア」と「黒い供物」を受け取れるほか、希少素材「原初の霊核」「純粋な原初の霊核」も獲得できます！これはミサゴの地底ブラックプールで産出される神秘的な霊核で、覚醒体のレベル上限を引き上げるのに役立ち、最大90レベルまで上昇できます！\n·「融災禁域」は定期的にステージ内容と報酬が更新され、通常は14日ごとに更新されます。当期の期間終了後、未受取の報酬は獲得できなくなりますので、シークレットキーパーは忘れずに期限内に完了・受取を行ってください～\n\n<Title:「禁域特殊ルール」>\n·融災禁域には独自の制限法則があります：同一の覚醒体とキーオーダー、同名の命輪は重複して出場できません。シークレットキーパーは初期遺物、モンスター、推奨レベルに応じて、今回の挑戦編隊を柔軟に選択できます。\n·挑戦完了後、より良い組み合わせを発見した場合は「リセット」機能を使って対応ステージの挑戦編隊をリセットできます。リセット後は覚醒体、キーオーダー、命輪を再び出場させることができますが、そのステージで獲得した特訓値も差し引かれます（報酬状態には影響しません）。\n·「融災禁域」では1回の助っ人を使用できます。助っ人の覚醒体と命輪は制限法則の影響を受けません。助っ人覚醒体を含む挑戦編隊をリセットした場合も、1回の助っ人回数が返還されます。\n\n<Title:「追加挑戦」>\n·いずれかのステージをクリアすると、そのステージの「追加挑戦」が解放され、より高い難易度の試練に挑めます。\n·追加挑戦は別途挑戦編隊を編成する必要があり、同様に制限法則の影響を受けます：同一の覚醒体とキーオーダー、同名の命輪は重複して出場できません。助っ人回数は通常挑戦と共有されます（全ゲームプレイで合計1回）。\n·追加挑戦をクリアすると5ポイントの特訓値を獲得でき、当期の特訓値合計に加算され、より多くの報酬の受取やランキング順位の向上に役立ちます。\n·「リセット」機能を使って追加挑戦編隊または通常挑戦編隊を個別にリセットできます。\n·追加クリア後に通常挑戦編隊をリセットした場合、追加挑戦編隊は新たな通常挑戦編隊に転換され、追加挑戦の進捗がクリアされ、追加クリアの特訓値が差し引かれます。\n\n<Title:「ランキング」>\n·現在、当期と前期の特訓値ランキング、および他のシークレットキーパーの融災禁域でのクリア情報を確認でき、シークレットキーパーへの参考情報として提供されます。\n·ランキングは当期の最高特訓値に達した時点の特訓値とクリア情報を表示します。リセットはランキングにも影響せず、クリア編隊情報の表示にも影響しません。"
  },
