  LanguageConfig_AssistanceSystemIntroduction_CN = {
    Text = "・守秘者が1名の覚醒体を救援に選択すると、相互フォローした他の守秘者が融蝕の廃墟、禁忌編纂、幻夢の深奥で救援覚醒体を使用し出撃可能になります。\n・他の守秘者が救援覚醒体を使用し調査に成功すると、薔薇金券×1000の報酬を獲得。1日に最大20回まで報酬を獲得できます。\n・薔薇金券の報酬が50回に達すると、守秘者は報酬の受け取り後に、救援報酬を引き続き獲得できるようになります。"
