  LanguageConfig_AwakerAssistRule_CN = {
    Text = "・「融蝕の廃墟」「禁忌編纂」「幻夢の深奥」「超越存在」などでは、相互フォローしている守秘者の救援覚醒体を1名選択して出撃できます。\n\n・救援覚醒体は現在の編成の界域制限を満たす必要があり、条件を満たさない救援覚醒体は出撃できません。チームを調整すれば出撃可能です。\n\n・一部のイベントでは特別な救援ルールがある場合があります。\n詳細については該当イベントの「イベント説明」を確認してください。"
