  LanguageConfig_AwakerFavorability_Description_Detail_CN = {
    Text = "<Title:【同調率獲得】>\n·調査、特務記録、意識潜行、幻夢深潜などのステージをクリアすると、出撃中の覚醒体が同調率を獲得できます。\n·覚醒体が発射するカードが多いほど、消費する行動力と狂気が多いほど、獲得できる同調率も多くなります。また、ステージの推奨レベルが高いほど、獲得できる同調率も多くなります。\n·シークレットキーパーのキーエネルギー消費が多いほど、出撃中の覚醒体が獲得できる同調率も多くなります。\n·手動戦闘中に獲得できる同調率は、「自動戦闘」を有効にした場合の 3 倍です。\n·助っ人を使用してステージをクリアすると、シークレットキーパーの出撃中の覚醒体が獲得できる同調率が 50% 増加します。\n·覚醒体を寮に招待すると、5 分ごとに同調率を 1 ポイント獲得できます。\n·オフライン中に 300 ポイントを超えて蓄積された場合、獲得速度は 15 分ごとに 1 ポイントに低下し、最大 3000 ポイントまで蓄積できます。\n\n<Title:【同調率レベル】>\n·覚醒体の同調率を集めることで同調率レベルを上げることができます。レベルが高いほど、より多くの覚醒体のボイスやストーリーが解放され、一部のレベルでは「ヘブンズコア」を獲得できます。\n·覚醒体の同調率が Lv15 に達した後、「心身同調」を通じて「絆の証」を消費することでレベル上限を Lv20 まで段階的に引き上げることができます。各レベルで「純粋な霊核の欠片」×5 を獲得でき、Lv20 に達した際にはさらに「輝き」を追加で獲得できます。\n·覚醒体の同調率が現在のレベル上限に達すると、それ以上蓄積されなくなります。引き続き獲得するには、先に心身同調を完了させる必要があります。"
