  LanguageConfig_BPOpenPreviewTxt_CN = {
    Text = "{s1}日{s2}時間後に新しい課題が開始"
  },
  LanguageConfig_BPRuleTxt2_CN = {
    Text = "\n\n<Title:【特殊課題】>\n・今期課題期間は{s1} - {s2}（GMT+8）、任務を完了して課題経験値を2倍獲得し、課題レベルを素早く上げましょう。"
  },
  LanguageConfig_BPRuleTxt_CN = {
    Text = "<Title:【課題カテゴリー】>\n・各期の課題では、「基本課題」がデフォルトで解放されます。守秘者は「上位課題」を解放することで、より豪華な報酬を獲得できます。\n・通常、各期の課題は28日間継続します。時にミサゴは継続時間がより短い特殊課題を開始することがあり、特殊課題期間中に獲得した課題経験値はすべて2倍になり、守秘者がより早く当期の課題を完了できるようサポートします！\n \n・28日間継続する課題：\n  ・「上位課題」の解放には「プラチナジェル」×680が必要で、解放時に「シルバーコア」×680を即時に獲得できます。\n  ・「核心課題」の解放には「プラチナジェル」×1280が必要で、解放時に「シルバーコア」×1460を即時に獲得できます。\n  ・「上位課題」から「核心課題」へのアップグレードには「プラチナジェル」×780が必要で、アップグレード時に「シルバーコア」×780を即座に獲得できます。\n \n・特殊課題：\n  ・課題期間中に獲得した「課題経験値」が2倍になります。\n  ・「上位課題」の解放には「プラチナジェル」×680が必要で、解放時に「シルバーコア」×680を即時に獲得できます。\n  ・「核心課題」の解放には「プラチナジェル」×980が必要で、解放時に「シルバーコア」×1070を即時に獲得できます。\n  ・「上位課題」から「核心課題」へのアップグレードには「プラチナジェル」×390が必要で、アップグレード時に「シルバーコア」×390を即座に獲得できます。\n\n<Title:【核心課題特典】>\n・「核心課題」を解放すると、本期の課題期間中に特典を獲得できます。\n・「日常訓練」の「基礎活性イオン」累積報酬で獲得できる「起点装置」、「ヘブンズコア」、「経験」、「シルバーコア」が3倍になります。「核心課題」を購入後、本期にすでに受け取った「基礎活性イオン」累積報酬の追加倍率分が補填されます。\n・戦闘中に「時系列逆行」を使用して、経過したターンに戻ることができます。\n・「対人戦」において、期間限定ですべてのカードを解放できます。\n\n<Title:【課題レベル】>\n・守秘者は秘境教室の日常訓練とウィークリー試訓を完了することで課題経験値を獲得し、課題レベルを上げて豪華な報酬を獲得できます。\n・「日常訓練」は9時にリフレッシュされ、「ウィークリー試訓」は毎週月曜日9時(GMT+8)にリフレッシュされます。\n・課題レベルが50に達すると、1レベル上がるごとに追加報酬を1つ獲得できます。"
  },
  LanguageConfig_BPSingleChooseTitle_CN = {
    Text = "獲得した報酬を選択してください"
  },
  LanguageConfig_BPTaskSubTabDaily_CN = {
