  },
  LanguageConfig_BPTaskTab_CN = {Text = "任務"},
  LanguageConfig_BPTimeFormat_CN = {Text = "残り{s1}"},
  LanguageConfig_BackTrack_CN = {
    Text = "リセット"
  },
  LanguageConfig_BacktrackAwaker_Rules_CN = {
    Text = "<Title:【育成リセット】>\n・この操作は覚醒体のすべてのレベルアップ、昇格、スキル、霊知深化状態をリセットし、消費した素材と金券はすべて返還されます。\n・覚醒体が消費したすべての界域昇格素材は、同じ数量とレア度の「初級昇格ボックス」、「中級昇格ボックス」、「高級昇格ボックス」に返還され、同じ数量とレア度の任意の界域昇格素材を選択できます。\n・覚醒体が消費したすべての界域スキル素材は、同じ数量とレア度の「初級スキル補給」、「中級スキル補給」、「高級スキル補給」に返還され、同じ数量とレア度の任意の界域スキル素材を選択できます。\n・覚醒体が消費したすべての「幸運のキャンディ」、「蝋人形の原型」、「漆黒の留め具」、「次元結晶」、「信仰の聖心」は、30倍の数量の「擬態凝晶」に返還されます。 \n<Title:【霊知啓発リセット】>\n・この操作は覚醒体の霊知啓発をリセットし、霊知啓発によるレベルの上限アップもリセットされます。また、霊知啓発で消費した素材はすべて返還されます。\n・覚醒体が消費または未使用の霊知啓発の欠片は、取得元に応じて異なるアイテムに返還されます。\n・「精神体カプセル」から交換されたものは「精神体カプセル」に返還されます。\n・限定覚醒から得た限定覚醒体から変換されたものは「返魂のコア」に返還されます。\n・「ドール」「オジール」「ロータン」については「調査勲章」×2500に返還されます。\n・「ラモンナ」「環行・ラモンナ」の場合は「欠片・ラモンナ」に返還されます。\n・「アイギス」「オレッタ」「エリカ」の場合は「融蝕の珠」×8000に返還されます。\n・その他の方法で得たものは「魔封瓶」に返還されます。\n<Title:【昏き海への帰還】>\n・この操作は「育成リセット」のすべての効果に加え、覚醒体自体もリセットされ、未解放状態になります。\n・覚醒体に装備されている命輪、密契はすべて外され、アイコンは使用不可になり、使用中の場合はデフォルトアイコンに切り替わります。\n・覚醒体の昇格報酬受取状態、同調率と同調率報酬受取状態はすべて保持され、再獲得時に引き継がれます。\n・覚醒体自体は取得元に応じて異なるアイテムに返還されます。期間限定イベント覚醒から得たイベント覚醒体は「返魂のコア」に返還され、その他の方法で得たものは「魔封瓶」に返還されます。\n<Title:【アイテム説明】>\n・「初級昇格ボックス」：使用時に純白の紙片、本能の精錬、記憶のコピー、認知テンプレートの中から1つ選べます。\n・「中級昇格ボックス」：使用時に純白の文書、理性の精錬、感情のコピー、精神テンプレートの中から1つ選べます。\n・「高級昇格ボックス」：使用時に純白の秘篇、精神の精錬、意識のコピー、霊知テンプレートの中から1つ選べます。\n・「初級スキル補給」：使用時に失色の蝶水晶、低茎ウミユリ、風乾した蛹、破損した鉱晶の中から1つ選べます。\n・「中級スキル補給」：使用時に輝色の蝶水晶、高茎ウミユリ、原生虫の蛹、隕石の破片の中から1つ選べます。\n・「高級スキル補給」：使用時に混沌の結晶、ユインタ百合、胞子ポリマー、ユカタンの星の中から1つ選べます。\n・「精神体カプセル」：使用時に解放済みSSRキャラの覚醒体の欠片から1つ選べます。\n・「魔封瓶」：使用時に「界域研究」の中から1体覚醒体を選べます。\n・「返魂のコア」：使用時に「界域研究」、過去のイベントキャラ覚醒、現在のイベントキャラ覚醒の中から1体覚醒体を選べます。"
  },
