  LanguageConfig_BacktrackWeapon_Rules_CN = {
    Text = "<Title:【強化リセット】>\n・この操作は運命の札のすべての強化状態をリセットし、消費した材料はすべて返却されます。\n\n・「循環基盤」で強化した場合、「循環基盤」を返却します。期間限定召喚で得た限定運命の札で強化した場合、「廻命のコア」を返却します。他の方法で強化した場合、「輪転の書」を返却します。\n\n<Title:【昏き海返却】>\n・この操作は「育成リセット」のすべての効果に加え、運命の札自体もリセットします。\n\n・期間限定召喚で得た限定運命の札の場合、「廻命のコア」を返却します。他の方法で得た場合、「輪転の書」を返却します。\n\n<Title:【アイテム説明】>\n・以下のアイテムは所持品画面で使用します。\n\n・「循環基盤」：任意の「SSR運命の札」の強化素材として使用可能です。\n\n・「輪転の書」：使用時に「輪転の相」から任意の「SSR運命の札」を1つ選んで獲得できます。\n\n・「廻命のコア」：使用時に「輪転の相」、過去の運命の札イベント召喚、現在の運命の札イベント召喚から任意の「SSR運命の札」を1つ選んで獲得できます。"
  },
