  LanguageConfig_Battle_Tips_DeathResist_CN = {
    Text = "戦闘中に致命傷を受けた際にこの確率で発動しライフ1で耐える。発動後、次のターンに算力2と2枚のドローを獲得し、チームの<CardKeyWord:死亡抵抗>が半減、以降獲得する<CardKeyWord:死亡抵抗>も半減し、調査終了まで持続する。\n混沌界域の覚醒体が1体以上いる場合、<CardKeyWord:死亡抵抗>初期値 +100%。"
