  LanguageConfig_BonusCardAwardText_CN = {
    Text = "強欲ボーナス"
  },
  LanguageConfig_BonusCardRateText_CN = {
    Text = "「豊穣の種核」が強欲ボーナスを獲得：<NetworkDelayGreen:{s1}>"
  },
  LanguageConfig_BonusCardTipsContent_CN = {
    Text = "1、特定の覚醒体や運命の札を所持すると適用されます。（参戦は不要）\n\n「波乱の情欲」ステージ報酬の「豊穣の種核」の追加ドロップが獲得できます。（リプレイを含む）\n詳細：\n・覚醒体「タイス」：\n霊知啓発0/1/2/3以上で20%/30%/40%/50%増加\n・SSR運命の札「慈悲の育み」：\n強化0/1/2/3以上で20%/30%/40%/50%増加\n・SR運命の札「熱い別れのキス」：\n強化0/1/2/3以上で20%/30%/40%/50%増加\n\n2、異なる覚醒体や運命の札の「強欲ボーナス」は累積されます。"
  },
  LanguageConfig_BonusCardTipsTitle_CN = {
    Text = "強欲ボーナス説明"
  },
  LanguageConfig_BonusRuleContent_A24Activity_CN = {
    Text = "1、特定の覚醒体や運命の札を所持すると適用されます。（参戦は不要）\n\n「記憶の収集」ステージ報酬の「記憶パズル」の追加ドロップが獲得できます。（リプレイを含む）\n詳細：\n・覚醒体「24」：\n霊知啓発0/1/2/3以上で20%/30%/40%/50%増加\n・SSR運命の札「奇体の反噬」：\n強化0/1/2/3以上で20%/30%/40%/50%増加\n・SR運命の札「銀ダラの決意」：\n強化0/1/2/3以上で20%/30%/40%/50%増加\n\n2、異なる覚醒体や運命の札の「理性ボーナス」は累積されます。"
  },
  LanguageConfig_BonusRuleContent_ArachneActivity_CN = {
    Text = "1、守秘者は特定の覚醒体または命輪（出陣は不要）を持っていると、「人形の舞台」ステージの任務報酬の「ベルベット座席券」に追加のドロップボーナスを与えることができます。具体的なボーナスは以下の通りです：\n·覚醒体「アラクネ」：霊知0/1/2/3以上、ボーナス20%/30%/40%/50%。\n·SSR命輪「永遠の織りの網」：重複位置0/1/2/3以上、ボーナス20%/30%/40%/50%。\n·SR命輪「運命の糸車」：重複位置0/1/2/3以上、ボーナス20%/30%/40%/50%。\n2、異なる覚醒体または命輪の「活動加成」は重複して計算されます。"
  },
  LanguageConfig_BonusRuleContent_CarabooActivity_CN = {
    Text = "1、シークレットキーパーが特定の覚醒体または命輪を所持している場合（出場不要）、「ウマーパティの宝物」のステージ任務報酬の「赤いリンゴ」「金のリンゴ」「飴リンゴ」に追加ドロップボーナスが付与されます。詳細なボーナスは以下の通りです：\n·覚醒体「カラブ」：霊知啓発0/1/2/3以上、ボーナス20%/30%/40%/50%。\n·SSR命輪「甘美な欺瞞」：重複位置0/1/2/3以上、ボーナス20%/30%/40%/50%。\n·SR命輪「穏やかな真実」：重複位置0/1/2/3以上、ボーナス20%/30%/40%/50%。\n2、異なる覚醒体または命輪の「【活動】ボーナス」は重複加算方式で計算されます。"
  },
  LanguageConfig_BonusRuleContent_CastorActivity_CN = {
    Text = "1、特定の覚醒体や命輪を所持すると適用されます。（参戦は不要）\n\n場合、「青空を越えて」ステージ報酬の「知識の書」「数理の書」「文学の書」の追加ドロップが獲得できます。（リプレイを含む）\n詳細：\n・覚醒体「カストル」：霊知啓発0/1/2/3以上で20％/30％/40％/50％増加\n・SSR命輪「耐え難い自由」：強化0/1/2/3以上で20％/30％/40％/50％増加\n・SR命輪「孤独な羽」：強化0/1/2/3以上で20％/30％/40％/50％増加\n\n2、異なる覚醒体や命輪のイベントボーナスは累積されます。"
  },
  LanguageConfig_BonusRuleContent_ClementineActivity_CN = {
    Text = "1、特定の覚醒体や命輪を所持すると適用されます。（参戦は不要）\n\n場合、「不安の緩和」ステージ報酬の「診断レポート」の追加ドロップが獲得できます。（リプレイを含む）\n詳細：\n・覚醒体「クレメンタイン」：霊知啓発0/1/2/3以上で20％/30％/40％/50％増加\n・SSR命輪「覆い隠された苦痛」：強化0/1/2/3以上で20％/30％/40％/50％増加\n・SR命輪「催眠の振り子」：強化0/1/2/3以上で20％/30％/40％/50％増加\n\n2、異なる覚醒体や命輪のイベントボーナスは累積されます。"
