    Text = "1、守秘者が特定の覚醒体または命輪を所持している場合（出撃不要）、「仮テキスト」ステージ任務報酬の「仮テキスト」に追加ドロップボーナスが付与されます。具体的なボーナスは以下の通りです：\n·覚醒体「太岁」：霊知啓発0/1/2/3以上、ボーナス20%/30%/40%/50%。\n·SSR命輪「仮テキスト」：強化0/1/2/3以上、ボーナス20%/30%/40%/50%。\n·SR命輪「仮テキスト」：強化0/1/2/3以上、ボーナス20%/30%/40%/50%。\n2、異なる覚醒体または命輪の「活動ボーナス」は加算方式で集計されます。"
  },
  LanguageConfig_BonusRuleContent_TawilActivity_CN = {
    Text = "1、特定の覚醒体や運命の札を所持すると適用されます。（参戦は不要）\n\n「最終テスト」ステージ報酬の「終末の指針」の追加ドロップが獲得できます。（リプレイを含む）\n詳細：\n・覚醒体「タヴィ」：\n霊知啓発0/1/2/3以上で20%/30%/40%/50%増加\n・SSR運命の札「隠世の転輪」：\n強化0/1/2/3以上で20%/30%/40%/50%増加\n・SR運命の札「真理の門」：\n強化0/1/2/3以上で20%/30%/40%/50%増加\n\n2、異なる覚醒体や運命の札の「終末の指針ボーナス」は累積されます。"
  },
  LanguageConfig_BonusRuleContent_ThaisActivity_CN = {
    Text = "1、特定の覚醒体や運命の札を所持すると適用されます。（参戦は不要）\n\n「波乱の情欲」ステージ報酬の「豊穣の種核」の追加ドロップが獲得できます。（リプレイを含む）\n詳細：\n・覚醒体「タイス」：\n霊知啓発0/1/2/3以上で20%/30%/40%/50%増加\n・SSR運命の札「慈悲の育み」：\n強化0/1/2/3以上で20%/30%/40%/50%増加\n・SR運命の札「熱い別れのキス」：\n強化0/1/2/3以上で20%/30%/40%/50%増加\n\n2、異なる覚醒体や運命の札の「強欲ボーナス」は累積されます。"
  },
  LanguageConfig_BonusRuleContent_TuluActivity_CN = {
    Text = "1、特定の覚醒体や運命の札を所持すると適用されます。（参戦は不要）\n\n「深海凝視」ステージ報酬の「疲弊の思念」「哀愁の思念」「歓喜の思念」の追加ドロップが獲得できます。（リプレイを含む）\n\n詳細：\n・覚醒体「トゥルー」：\n霊知啓発0/1/2/3以上で20%/30%/40%/50%増加\n\n・SSR運命の札「神王の讃歌」：\n強化0/1/2/3以上で20%/30%/40%/50%増加\n\n・SR運命の札「青石の玉座」：\n強化0/1/2/3以上で20%/30%/40%/50%増加\n\n2、異なる覚醒体や運命の札の「思念ボーナス」は累積されます。"
  },
  LanguageConfig_BonusRuleContent_WandaActivity_CN = {
    Text = "1、特定の覚醒体や運命の札を所持すると適用されます。（参戦は不要）\n\n「燃える饗宴」ステージ報酬の「原生の脛骨」「円形菊石」「螺旋遺跡」の追加ドロップが獲得できます。（リプレイを含む）\n詳細：\n・覚醒体「ワンダ」：\n霊知啓発0/1/2/3以上で20%/30%/40%/50%増加\n・SSR運命の札「女王の戒律」：\n強化0/1/2/3以上で20%/30%/40%/50%増加\n・SR運命の札「イサラウの眼差し」：\n強化0/1/2/3以上で20%/30%/40%/50%増加\n\n2、異なる覚醒体や運命の札の「秘宝ボーナス」は累積されます。"
  },
  LanguageConfig_BonusRuleContent_XuActivity_CN = {
    Text = "1、守秘者は特定の覚醒体または命輪を所有している場合(出陣は必要ありません)、「玄女無相」ステージの任務報酬における「梨膏糖」のドロップ率に追加のボーナスを得ることができます。具体的なボーナスは以下の通りです：\n·覚醒体「徐」：霊知0/1/2/3以上、加算20％/30％/40％/50％。\n·SSR命輪「無駄に眉をひそめる」：重複位置0/1/2/3以上、加算20％/30％/40％/50％。\n·SR命輪「ウメの餌」：重複位置0/1/2/3以上、加算20％/30％/40％/50％。\n2、異なる覚醒体または命輪の「イベントボーナス」は重複して計算されます。"
