  LanguageConfig_CosmeticsRandChestRateText_CN = {
    Text = "<Title:確率説明>\n1、使用するたびに10%の確率で無形者のギフト券の「専用アイコンとスタンプ」を獲得し、90%の確率で過去の核心課題や対人戦シーズンの限定アイコンとスタンプを獲得できます。\n2、すべての専用アイコンとスタンプは10%の確率で均等に分けられます。具体的には以下の「専用アイコンとスタンプ一覧」をご覧ください。\n3、核心課題の限定アイコンとスタンプは、該当課題が終了してから約1年後にドロップリストに追加されます。対人戦シーズンの報酬のスタンプは、そのシーズン終了後すぐにドロップリストに追加されます。\n4、すべての過去の限定アイコンとスタンプは90%の確率で均等に分けられます。特に、「無形者の招待状」も過去の限定アイコンとスタンプの1つと見なされ、ドロップリストに他の過去の限定アイコンやスタンプがない場合、このとき「無形者の招待状」は90%の確率を独占します。\n5、すでに持っているアイコンやスタンプを獲得した場合、1つの「無形者の招待状」に変換されます。一定数の「無形者の招待状」を収集して使用することで、獲得していないアイコンまたはスタンプを「無形者のギフト券」から選ぶことができます。\n\n<Title:専用アイコンとスタンプ一覧>\n1、専用アイコンには以下が含まれます：\n銀の鍵の名のもとに：アルバ、銀の鍵の名のもとに：ゴリアテ、銀の鍵の名のもとに：ユウハシュ、銀の鍵の名のもとに：カーシア、銀の鍵の名のもとに：ハレト、銀の鍵の名のもとに：デクスター、銀の鍵の名のもとに：シルヴィア、銀の鍵の名のもとに：ウィリアム。\n2、専用スタンプには以下が含まれます：\n発狂ミサゴ：ユウハシュ・私は、発狂ミサゴ：ブラウン・知らない、発狂ミサゴ：ヘロット・殺すぞ、のんびりミサゴ：シルヴィア・お茶、のんびりミサゴ：ハレト・徹夜、のんびりミサゴ：オジール・敬礼、のんびりミサゴ：ロータン・兄弟です、のんびりミサゴ：ラモンナ・額に手を当てる、のんびりミサゴ：ドール・電池残量不足、通信中ミサゴ：守秘者・私？、かしこいミサゴ：ゴリアテ・強い、かしこいミサゴ：レーア・涙、かしこいミサゴ：ナウティラ・え？、かしこいミサゴ：ジェンキン・考える、かしこいミサゴ：アグリッパ・密かに観察、かしこいミサゴ：カエクス・恨み、ちびちびミサゴ：ジェンキン・舌を出す。"
  },
