  LanguageConfig_DailyChallengeAwardIllustrateContent_CN = {
    Text = "1、本日の「幻夢の深奥」のクリア最高難易度により、翌日の「融蝕の珠」報酬が決まります。各難易度ごとの報酬は以下の通りです：\n・幻夢の深奥Ⅰ：融蝕の珠×300\n・幻夢の深奥Ⅱ：融蝕の珠×400\n・幻夢の深奥Ⅲ：融蝕の珠×500\n・幻夢の深奥Ⅳ：融蝕の珠×600\n・幻夢の深奥Ⅴ：融蝕の珠×700\n・幻夢の深奥Ⅵ：融蝕の珠×800\n・幻夢の深奥Ⅶ：融蝕の珠×900\n・幻夢の深奥・超難度：融蝕の珠×900\n2、報酬は翌日メールで送られますので、忘れずにご確認ください。\n3、「幻夢の深奥」や「外勤代理」に参加した守秘者が同日に「対人戦」にも参加した場合、翌日9:00の「融蝕の珠」報酬は、毎日の幻夢報酬と「対人戦」ランキング報酬のうち、より高い方が適用されます。"
