  LanguageConfig_DailyChallengeExpAttenuationRulesTips_CN = {
    Text = "・「守秘者レベル」または「チーム平均レベル」が挑戦ステージの推奨レベルを大幅に上回る場合、深奥経験値の獲得が減少します。"
