  LanguageConfig_DailyChallengeExpOutBase_CN = {
    Text = "基礎報酬"
  },
  LanguageConfig_DailyChallengeExpRewardCoefficientLevelTips_CN = {
    Text = "・「守秘者レベル」がステージの推奨レベルに近い場合、調査終了後「深奥経験値」を獲得できます。\n   ・「挑戦の旅」：ステージ難易度の「推奨レベル」が 「守秘者レベル」- 40より高い場合、基礎深奥経験値を獲得できます。\n   ・「超越の旅」：ステージ難易度の「推奨レベル」が「守秘者レベル」- 20より高い場合、さらに追加で基礎深奥経験値を獲得できます。"
  },
  LanguageConfig_DailyChallengeExpRewardTask1_CN = {
    Text = "挑戦の旅"
  },
  LanguageConfig_DailyChallengeExpRewardTask2_CN = {
    Text = "超越の旅"
  },
  LanguageConfig_DailyChallengeInstructionsV2_CN = {
    Text = "<Title:【幻夢深潜】>\n·初期遺物・ステージ遺物は毎週月曜日9時（GMT+8）に変更されます。\n·挑戦するたびにランダムな挑戦シナリオに入ります。\n<Title:【深淵経験】>\n·「守秘者レベル」がステージの推奨レベルに近い場合、挑戦に勝利すると深淵実績が達成され、「深淵経験」を獲得できます。\n   ·「チャレンジジャーニー」：挑戦難易度の「推奨レベル」が「守秘者レベル」- 40レベルより高い場合、基礎深淵経験を獲得できます。\n   ·「超越ジャーニー」：挑戦難易度の「推奨レベル」が「守秘者レベル」- 20レベルより高い場合、さらに基礎深淵経験を1つ追加で獲得できます。\n<Title:【深淵レベル】>\n·深淵経験が一定値に達すると、深淵レベルが上昇します。レベルアップごとに豊富な報酬を獲得できます。\n<Title:【シーズン更新】>\n·通常、シーズンは28日ごとにリセットされます。\n·調査終了時に調査スコアが付与され、各シーズンで本シーズン最高の調査スコアが記録されシーズンランキングに使用されます。スコアを上げるために繰り返し調査できます。他の守秘者と調査スコアが同じ場合、同順位とみなされます。\n·シーズン終了時に本シーズンのランキングが集計され、メールで本シーズンのランキング報酬が送付されます。守秘者は「ランキング」-「ランキング報酬」をクリックしてランキング報酬を確認できます。\n·各シーズンにはシーズン任務があり、シーズン任務を完了すると豊富な報酬を獲得できます。シーズン任務はシーズン終了時にリセットされます。\n<Title:【シーズンごとの覚醒体強化】>\n·各シーズンの各界域では、2体のランダムな覚醒体が本シーズンの幻夢深潜行動中に狂暴化し、体力・攻撃力・防御力が50％上昇します。\n<Title:【調査スコア】>\n·調査終了時に現在のステージの難易度基礎点と達成したスコア項目で集計されます。高い難易度に挑戦するほど難易度基礎点が高くなります。\n·下記が具体的なスコア項目です。\n1、「時系列の砂時計」：初期ラウンドは50、残り1ラウンドごとに追加で20点を獲得。\n2、「深淵の呼び声」：強化覚醒体を1/2/3/4体出撃させた場合、250/500/750/1000点を獲得。\n3、「幻境救援」：緊急れいち体を1回使用するごとに調査スコアが20％低下し、複数回発動した場合は複数回乗算されます。\n4、「夢拓く先駆者」：その日の初回プレイで500点を獲得。"
  },
  LanguageConfig_DailyChallengeInstructions_CN = {
    Text = "<Title:【幻夢深潜】>\n・初期遺物、ステージ内遺物は毎週月曜日9:00（GMT+8）に変化します。\n・挑戦のたびに、ランダムなステージに変化します。\n<Title:【深淵経験】>\n・「守秘者レベル」がステージの推奨レベルに近い場合、クリアすることで深淵実績が達成され、「深淵経験」を獲得できます。\n   ・「挑戦の旅」：ステージ難易度の「推奨レベル」が「守秘者レベル」-40レベルより高い場合、基礎深淵経験を獲得できます。\n   ・「超越の旅」：ステージ難易度の「推奨レベル」が「守秘者レベル」-20レベルより高い場合、さらに追加で基礎深淵経験を獲得できます。\n<Title:【深淵レベル】>\n・深淵経験が一定値に達すると、深淵レベルが上昇します。レベルが上がるごとに豊富な報酬を獲得できます。\n<Title:【シーズン更新】>\n・通常、シーズンは28日ごとにリセットされます。\n・調査終了時に調査スコアを獲得します。毎シーズン、最高の調査スコアがそのシーズンのランキングに記録され、繰り返し調査を行うことでスコアを更新できます。他の守秘者と調査スコアが同じ場合は、同一順位として扱われます。\n・シーズン終了時にそのシーズンのランキングが集計され、メールでシーズンランキング報酬が送付されます。守秘者は「ランキング」-「ランキング報酬」を選択することでランキング報酬を確認できます。\n・各シーズンにはシーズン任務があり、シーズン任務を完了することで豊富な報酬を獲得できます。シーズン任務はシーズン終了時にリセットされます。\n<Title:【毎シーズンの強化覚醒体】>\n・毎シーズン、各界域からランダムに選ばれた2体の覚醒体が、そのシーズンの幻夢深潜行動において躁狂状態となり、体力・攻撃力・防御力が50%上昇します。\n<Title:【調査スコア】>\n・調査終了後、ステージの難易度基礎点と達成した評価項目に基づき集計されます。難易度が高いほど、難易度基礎点も高くなります。\n・以下は具体的な評価項目です。\n1、「時系列の砂時計」：開始時50ターン。残り1ターンごとに20点を獲得。\n2、「深淵の呼びかけ」：強化覚醒体を1/2体編成して出撃した際、250/500点を獲得。\n3、「幻境救援」：緊急れいち体を1回使用するごとに調査スコアが20%減少。複数回発動するとその分乗算されます。\n4、「拓夢先駆者」：毎日初回プレイ時に500点を獲得。"
  },
