  LanguageConfig_DeepSeaInvasionDefensiveActiviityTips13_CN = {
    Text = "「猫海淘銀」ではレベル補償メカニズムがあり、すべての守秘者が共に捕獲できるようになっています！\nレベル補償ルールは以下の通りです：\n·調査チームの中で、レベルが60未満の覚醒体は今回の挑戦で60レベルに補償されます。\n·調査チームの中で、スキルレベルが5未満の覚醒体は今回の挑戦で5レベルに補償されます。\n·調査チームの中で、「狂気の予兆」が6未満の覚醒体は今回の挑戦で6レベルに補償されます。\n·調査チームの中で、「霊塑適性」が5未満の覚醒体は今回の挑戦で5レベルに補償されます。\n ·守秘者のレベルが60未満の場合、今回の挑戦で60レベルに補償されます。"
