  LanguageConfig_DiamondDonateDesc_CN = {
    Text = "あなたが寄付したプラチナジェルは非常に貴重です。\n融蝕研究や校舎建設に使われ、ミサゴの一部となり、皆と共に忘れられない未来へと進んでいきます。\n銀の鍵の導きがあらんことを。"
