  LanguageConfig_DiamondDonateTipContent_CN = {
    Text = "<Title:寄付ルール>\n·「プラチナジェル寄付」で消費されたプラチナジェルは累計寄付値に計上されます。\n·また、「召喚」でシルバーコアが不足している場合に直接寄付されたプラチナジェルも計上されます。\n<Title:報酬ルール>\n·プラチナジェル1滴の寄付につき1点の貢献値が得られます。\n·貢献値が2500に達するごとに特別な返礼が1つ得られます。\n·20回の返礼で1サイクルとなります。\n·各サイクルの総返礼内容は以下の通りです：「精粋原初霊核」×1、「原初霊核」×3、「賢者の石」×6、「追憶の羽ペン」×800、「無形者の礼券」×100、「千面印章」×5000、「薔薇金券」×50000000。"
