  LanguageConfig_EnergyMonthCardRuleContent_CN = {
    Text = "【エンフェリンパスの紹介】\nエンフェリンパスを購入すると、「シルバーコア」×680と30日のエンフェリンパス有効期間がすぐに提供されます。\nエンフェリンパス期間中、毎日メールボックスから「エンフェリン」×300と「追憶の羽ペン」×30を受け取れます。毎日9:00にリセットされます【GMT+8】。\n \n【注意事項】\nエンフェリンパスの有効期間が180日以下の場合に再購入すると、総有効期間が延長されます。\nエンフェリンパスの有効期間が180日を超える場合は再購入できません。\n特別な理由で重複購入が発生した場合、総有効期間は加算されず、「シルバーコア」×680が直接返還されます。\nエンフェリンパス期間中に未受領だった「エンフェリン」と「追憶の羽ペン」は返還されません。"
