  },
  LanguageConfig_ExchangeShopRules_CN = {
    Text = "<Title:交換商店>\n・守秘者は各交換商店で対応する通貨を消費して商品を交換できます。\n・守秘者の調査レベルが上がると、交換商店もアップグレードされ、新しい内容が解放されます。\n・交換商店内の商品は一定期間ごとに自動で在庫が更新されます。\n\n<Title:薔薇金券交換>\n・守秘者はメイン調査での初回クリアや「融蝕の墟：金券捜索」、「派遣報酬」、「課題報酬」、期間限定イベントの報酬で「薔薇金券」を獲得できます。\n\n<Title:根源の澱交換>\n・守秘者は召喚を通じて「根源の澱」を獲得できます。\n\n<Title:調査勲章交換>\n・守秘者はメイン調査で三つ星の星評価を獲得するか、「超越存在」を通じて「調査勲章」を獲得できます。\n\n<Title:黒い供物交換>\n・守秘者は「闇の境界」または「融災禁区」を通じて「黒い供物」を獲得できます。\n\n<Title:融珠交換>\n・守秘者は「通常任務：今週の試練」を通じて「融蝕の珠」を獲得できます。"
  },
