  LanguageConfig_FriendInvitationRule_CN = {
    Text = "<Title:招待イベント>\n1.守秘者は招待コードを共有して新しい守秘者をミサゴキャンパスに招待し、一緒に冒険の旅に出ることができます。\n2.招かれた守秘者が任務を完了すると、任務報酬として「銀の鍵の輝き」を受け取れ、一定数に達することで、豪華な報酬を受け取れます！\n3.守秘者のレベルが5/10/15/20に達すると、それぞれ20/20/20/40「銀の鍵の輝き」を獲得できます。\n4.各守秘者は最大50人の招かれた守秘者から任務報酬を受け取ることができ、超えた人数分については任務報酬が提供されません。\n5.招かれた守秘者が調査レベル5に達してはじめて、正式な招待人数にカウントされます。\n<Title:招待の紐付け>\n1.守秘者は招待コードを入力して招待したプレイヤーと紐付けを行い、すぐにシルバーコア×300の報酬を獲得できます！\n2.各守秘者はミサゴ到着から最初の7日間のみ、招待コードの入力ができ、期限を過ぎると「招待の紐付け」機能は利用できなくなります。"
  },
