  },
  LanguageConfig_LotteryPhoneticDialogue50_CN = {
    Text = "ひとりであの世界に流れ着いたとき、ある人からたくさん、たくさん、いろんなことを教えてもらった。今でも、ずっと勉強し続けてるんだ。"
  },
  LanguageConfig_LotteryPhoneticDialogue51_CN = {
    Text = "あなたは誰かに、何も隠さず愛されたことある？それとも、すべてを捨てて誰かを愛したことは？\nそれって、とても素敵なことだと思う。"
  },
  LanguageConfig_LotteryPhoneticDialogue52_CN = {
