  LanguageConfig_LotteryRuleContent_CN = {
    Text = "1、「コレットの温室」には3つの花壇があり、開放時間は以下の通りです：\n・「菖蒲の花壇」：7月15日15:00。\n・「桔梗の花壇」：7月17日15:00。\n・「薔薇の花壇」：7月19日15:00。\n2、1回の交換ごとに「憂愁の詩文」/「後悔の詩文」/「歓喜の詩文」を1000消費し、花壇のアイテム報酬から5つをランダムで獲得します。\n3、各花壇のアイテム報酬は「特別アイテム」と「通常アイテム」の2種類に分かれます。リセット時に「特別アイテム」報酬の残量を上限まで戻すことができます。\n具体的なルールは以下の通りです：\n（1）最初2回までのリセット：「特別アイテム」の残量が無くなった場合、守秘者はリセットを選ぶことができ、「特別アイテム」と「通常アイテム」の残量を上限まで戻せます。\nもしくは、そのまま交換を続けることもできますが、「通常アイテム」も残量が無くなった場合は、リセットを行う必要があります。\n（2）3回目以降のリセット：「通常アイテム」の残量が無くなった場合のみリセット可能になります。リセットにより「通常アイテム」の残量を上限まで戻せますが、「特別アイテム」は戻りません。\n4、8月5日15:00以降、未交換の「詩文」は200個ごとに「薔薇金券×5000」に交換されますので、守秘者はメールを確認してください。"
