  LanguageConfig_PVPGoodBtnUnClickableStateTips_CN = {
    Text = "対人戦相手にいいね済み"
  },
  LanguageConfig_PVPInstructions_CN = {
    Text = "<Title:【対人戦】>\n・「対人戦」は《忘却前夜》の追加モードです。各シーズンでカードやゲームプレイが大幅にリメイク・変更され、よりバランスの取れた、より興味深いゲーム環境が提供されます。そのため、コンテンツ攻略のための資材の投入は慎重に行ってください。\n<Title:【マッチングについて】>\n・「対人戦」は2人用のゲームです。マッチング機能を通じて一定時間待機し、対戦相手を探します。実力が近い相手と優先的にマッチングされます。\n・同時マッチング：守秘者は「プリセットモード」と「ドラフトモード」の両方にチェックを入れて、両モードで同時にマッチングを行うことができます。これにより、対戦相手が見つかるまでの待ち時間を効果的に短縮できます。\n・精密マッチング：この設定をオンにすると、より実力の近い相手を探しますが、待ち時間は長くなります。オフにすると、待ち時間は短縮されますが、実力差のある相手と当たる可能性が高まります。\n・模擬対戦相手：この設定をオンにすると、マッチングの状況に応じて模擬対戦相手が割り振られるようになり、待ち時間が短縮されます。オフにした場合は実在するプレイヤーのみとマッチングするため、待ち時間が長くなります。\n<Title:【ポイントランキング】>\n・ポイントルール：初期ポイントは0で、対人戦にてポイントを獲得します。\n・ポイント変動：対人戦時に双方のポイントが同じ場合は、勝者は総ポイントの5％を獲得し、敗者は同等のポイントを失います。\n・初心者保護：ポイント1500未満では、勝利時により多くのポイントを獲得し、敗北時には少ないポイントを失います。\n・強敵挑戦：強敵に勝つと多くのポイントを獲得し、敗北すると少ないポイントを失います。弱敵に勝つと少ないポイントを獲得します。\n・ポイントの独立：「プリセットモード」と「ドラフトモード」はそれぞれ独立したポイントを持ちますが、どちらも上記のポイントルールが適用されます。\n<Title:【シーズン更新】>\n・シーズンリセット：通常、シーズンは28日ごとにリセットされます。リセット後、全員のポイント3000以上の部分は半分になります。\n・シーズンランキング：「プリセットモード」と「ドラフトモード」はそれぞれ独立したシーズンとシーズンランキングを持ち、シーズンランキング報酬は各シーズン終了時に集計されます。\n・ランキング条件：当シーズン内に1回参加すると対応モードのシーズンランキングに表示され、シーズン内の最高ポイントに基づいてランキングが決定されます。当シーズン内に1回勝利すると、シーズン終了時に現在のシーズンランキングに基づいて報酬が集計されます。\n・シーズン任務：「プリセットモード」と「ドラフトモード」にはそれぞれシーズン任務があり、完了すると豊富な報酬を獲得できます。シーズン任務はシーズン更新時にリセットされます。\n<Title:【プリセットモード】>\n・「プリセットモード」は対人戦の基本モードです。あらかじめ準備した編成を使用して相手と対戦します。マッチングを開始する前に自分の編成を選択し、未知の編成を持つ相手と戦います。\n<Title:【ドラフトモード】>\n・「ドラフトモード」は対人戦の上級モードです。チームを事前に編成することなくマッチングが可能です。戦闘開始前に、双方は「覚醒体」「運命の札」「キーオーダー」が含まれるカード群から交互にカードを選び、自分だけのデッキを構築して対戦に臨みます。\n・各対戦において、システムがランダムに1つの「遺物」を選出し、その対戦中に効果を発揮します。"
  },
  LanguageConfig_PVPMatchDefeat_CN = {
