  LanguageConfig_PVPRankingRuleDesc_CN = {
    Text = "<Title:【ポイントランキング】>\n・【プリセットモード】と【ドラフトモード】はそれぞれ独立したシーズンとシーズンランキングを持ち、シーズンランキング報酬は各シーズン終了時に集計されます。\n・当シーズン内に1回参加すると対応モードのシーズンランキングに表示され、シーズン内の最高ポイントに基づいてランキングが決定されます。当シーズン内に1回勝利すると、シーズン終了時に現在のシーズンランキングに基づいて報酬が集計されます。\n<Title:【ランキング割合】>\n・対人戦称号は参加者のポイントランキングに基づき、以下の割合で決定されます：\n     ・レジェンド：上位2％\n     ・マスター：2％〜10％\n     ・エリート：10％〜25％\n     ・ベテラン：25％〜50％\n     ・ミドル：50％〜75％\n     ・ルーキー：下位75％\n・同じポイントの場合、ランキングの先後により順位が決まりますが、対人戦称号と報酬はそのポイントの最高ランクに基づきます。"
