  LanguageConfig_PasswordBattleQueueButton_CN = {Text = "待機中"},
  LanguageConfig_PasswordBattleRuleTips_CN = {
    Text = "・パスワード対戦：対戦を作成後、ソーシャルメディアやメッセージアプリで<color=#5EF2FF>パスワード</color>を共有して招待できます。他の守秘者は<color=#5EF2FF>パスワード</color>を入力して対戦に参加できますが、一度に一人としか対戦できないため、先着順です。対戦が開始されると、他の招待された守秘者は参加できません。\n・対戦拒否：対戦したくない守秘者がいる場合、対戦を拒否できます。拒否が多いとブロックリストの警告が表示され、ブロックリストでその人の参加を防げます。解除するまで有効です。"
