  LanguageConfig_PermanentActivityRuleContent_CN = {
    Text = "<Title:記憶回廊>\n·「記憶回廊」マークが付いたイベントは、イベント期間終了後に「記憶回廊」に収録され、引き続き「記憶回廊」で対応するコンテンツやストーリーを体験できます。\n<Title:収録ルール>\n·「記憶回廊」マークが付いたイベントには豊富な期間限定報酬があります。イベント期間終了後は期間限定報酬を受け取れなくなりますので、秘密の守り手の皆さんはお早めに受け取りください。\n·イベントが「記憶回廊」に収録された後、それまでの進捗は自動的に保持されますので、引き続き体験できます。"
