  LanguageConfig_PlayerExpRuleContent_CN = {
    Text = "<Title:最高位の称賛>\n1、「知識の贈り物」イベント中、各タスクを完了することで「最高位の称賛」効果を獲得し、守秘者経験値の獲得量が最大100%増加。複数の「最高位の称賛」の効果が同時に存在する場合、最高の増加効果が適用されます。\n2、より高い「最高位の称賛」効果を解放または獲得した場合、増加割合と現在の増加可能な守秘者経験値総量に基づき、追加の守秘者経験値を即座に獲得。\n3、「最高位の称賛」を解放後、守秘者が経験を獲得するたびに、対応する増加割合の追加経験を獲得。\n4、注意：「最高位の称賛」による追加の守秘者経験値は、増加可能な総量には含まれません。\n5、現在増加可能な守秘者経験値総量：{s1}。\n6、増加により追加獲得した守秘者経験値：{s2}（{s3}%）"
