  LanguageConfig_RPGJJC_Desc_CN = {
    Text = "「演習証書」を使って他の守秘者の防御チームと挑戦でき、勝利すると順位が上がります。また、自身の防御チームを配置しないと、他の守秘者に挑戦されて順位が下がる可能性があります。順位が高いほど毎時間に「演習勲章」の取得量が増えます。「演習証書」は時間が経つと自動的に取得でき、「演習勲章」は交換所で薔薇金券や霊知の薬剤などのアイテムに交換可能。"
