  LanguageConfig_RailWayLevelAdjustmentTipsContent_CN = {
    Text = "「疾走する歓喜の特急」にはレベル補償メカニズムがあり、具体的なルールは以下の通りです：\n  ・調査チーム内で、レベルが60未満の覚醒体は今回の挑戦で60に補償されます。\n  ・調査チーム内で、スキルレベルが5未満の覚醒体は今回の挑戦で5に補償されます。\n  ・調査チーム内で、「狂気の予兆」が6未満の覚醒体は今回の挑戦で6に補償されます。\n  ・調査チーム内で、「霊塑適性」が5未満の覚醒体は今回の挑戦で5に補償されます。\n  ・守秘者のレベルが60未満の場合、今回の挑戦で60に補償されます。"
