  LanguageConfig_RailWayResonanceRuleContent_CN = {
    Text = "1、 「疾走する歓喜の特急」でより豊富な共鳴強化を行い、守秘者たちに強力な支援を提供します。\n2、 「沿途の思い出」で共鳴アップグレード素材を獲得でき、素材を消費することで共鳴効果を発動できます。\n3、各段階で調査行動の共鳴イベントがあり、調査行動の共鳴イベントに入ると対応する章の強力な共鳴効果が得られ、その効果は調査が終了するまで持続します。\n4、 「小」N「の協力」で得られる共鳴効果は、調査開始から調査終了まで持続します。"
  },
  LanguageConfig_RailWayRulesContentV2_CN = {
    Text = "<Title:遊び方の紹介>\n1、「疾走する歓喜の特急」は「星辰篇」のルールを採用した連続チャレンジモードです。シークレットキーパーは変化に富んだランダムな遭遇の中で、複数の調査に登場した最終ボスに連続して挑戦します！\n2、遊び方において遺物の保有上限は最大36個まで引き上げることができます。\n3、チャレンジ中に3種類の調査における強力な「共鳴」効果を同時に保有し強化することができます。\n4、緊急れいち体を1回使用するごとに、今回のチャレンジで獲得できる「VIPポイント」が20％減少します。\n5、途中退出して進行状況を保留することができますが、チームのステータスは外部の育成変化に合わせて同期更新されません。進行状況は前回のチャレンジから最大7日間保留されます。保留期間中にチャレンジを継続しない場合はチャレンジを放棄したとみなされ、進行状況は保留されなくなります。\n\n<Title:レベル補正>\n「列車の出発」に参加するとレベル補正が適用されます。具体的なルールは以下の通りです：\n  ·調査チームにおいて、レベルが60未満の覚醒体は今回のチャレンジ中に60レベルに補正されます。\n  ·調査チームにおいて、スキルレベルが5未満の覚醒体は今回のチャレンジ中に5レベルに補正されます。\n  ·調査チームにおいて、「狂気の予兆」が6未満の覚醒体は今回のチャレンジ中に6レベルに補正されます。\n  ·調査チームにおいて、「霊塑適性」が5未満の覚醒体は今回のチャレンジ中に5レベルに補正されます。\n  ·シークレットキーパーのレベルが60未満の場合、今回のチャレンジ中に60レベルに補正されます。\n\n<Title:ステージの段階>\n1、1回のチャレンジは合計3つの段階に分かれており、各段階のメインエネミーと共鳴効果は対応する範囲内でランダムに生成されます：\n  ·第一段階：「忘却篇」第1章〜第4章の内容に対応。\n  ·第二段階：「忘却篇」第5章〜第8章の内容に対応。\n  ·第三段階：「星辰篇」第1章〜第4章の内容に対応。\n ·狂気の難易度では、第三段階のチャレンジを完了した後、追加で第四段階の最終ボス「タヴィ」に挑戦します。\n2、段階のボスを倒した後、ランダムな3つの「時の振り子」から1つを選んで獲得できます。\n\n<Title:難易度と初期遺物>\n今回のチャレンジには3つの難易度が設定されており、各難易度には異なるステージ報酬と初期遺物があります。各シークレットキーパーはチャレンジ難易度を選択する前に詳細情報を確認できます。\n\n<Title:ステージ報酬>\n1、各難易度のエリートとボスを倒すことで「VIPポイント」を獲得でき、「VIPポイント」は「優雅室の仕様」レベルを上げて報酬を獲得するために使用します。\n  ·第一段階：エリートを倒す/ボスを倒すで「VIPポイント」×25/75を獲得\n  ·第二段階：エリートを倒す/ボスを倒すで「VIPポイント」×50/150を獲得\n  ·第三段階：エリートを倒す/ボスを倒すで「VIPポイント」×75/225を獲得\n2、チャレンジの難易度が高いほど、より多くの「VIPポイント」を獲得できます。\n  ·【難しい難度】：3つの段階を完了して獲得できる「VIPポイント」が150％増加\n\n  ·【狂気の難易度】：3つの段階を完了して獲得できる「VIPポイント」が400％増加\n ·最終ボス「タヴィ」を倒した後、追加で「VIPポイント」×1500を獲得できます。\n\n<Title:シーズン更新>\n1、「貴賓名簿」はチャレンジで優秀な成績を収めたシークレットキーパーを記録します。各シーズン中に1回チャレンジし、「VIPポイント」の獲得に成功したシークレットキーパーが「貴賓名簿」に入ることができます。\n2、「貴賓名簿」のシーズンランキングは、1回のチャレンジで獲得した最多の「VIPポイント」と使用した最少の「ターン数」を基準とし、繰り返しチャレンジしてランキングを上げることができます。\n3、シーズン終了後、メールにて今シーズンの「貴賓名簿」のランキング報酬が精算されます。\n4、各シーズンにはシーズン任務があり、シーズン任務を完了することで豊富な報酬を獲得できます。シーズン任務は毎回のシーズン更新時にリセットされます。\n5、シーズン切り替え時、まだ戦闘中のステージはチャレンジ完了後に最新のシーズン任務を直接完了できますが、「貴賓名簿」には入ることができません。"
  },
  LanguageConfig_RailWayRulesContent_CN = {
    Text = "<Title:ゲームプレイ概要>\n1、「疾走する歓喜の特急」は「星辰篇」のルールを採用した連続挑戦モードです。シークレットキーパーは変化に富んだランダムな遭遇の中で、これまでの調査に登場した最終ボスに連続して挑戦します！\n2、ゲームプレイ中の遺物保有上限は最大36個まで引き上げることができます。\n3、挑戦中に調査の強力な「共鳴」効果を同時に3種類所持・強化できます。\n4、緊急れいち体を1回使用するごとに、今回の挑戦で獲得する「VIPポイント」が20%減少します。\n5、途中退出して進捗を保留することができますが、編隊のステータスは外部の育成変化に合わせて同期更新されません。進捗は前回の挑戦から最大7日間保留されます。保留期間中に挑戦を継続しなかった場合は挑戦放棄とみなされ、進捗は保留されなくなります。\n\n<Title:レベル補正>\n「列車出発」に参加するとレベル補正が適用されます。詳細なルールは以下の通りです：\n  ·調査編隊内でレベルが60未満の覚醒体は、今回の挑戦中に60レベルに補正されます。\n  ·調査編隊内でスキルレベルが5未満の覚醒体は、今回の挑戦中に5レベルに補正されます。\n  ·調査編隊内で「狂気の予兆」が6未満の覚醒体は、今回の挑戦中に6レベルに補正されます。\n  ·調査編隊内で「霊塑適性」が5未満の覚醒体は、今回の挑戦中に5レベルに補正されます。\n  ·シークレットキーパーのレベルが60未満の場合、今回の挑戦中に60レベルに補正されます。\n\n<Title:ステージ段階>\n1、1回の挑戦は合計三つの段階に分かれており、各段階のメイン敵と共鳴効果は対応する範囲内でランダムに生成されます：\n  ·第一段階：「忘却篇」第一章〜第四章の内容に対応。\n  ·第二段階：「忘却篇」第五章〜第八章の内容に対応。\n  ·第三段階：「星辰篇」第一章〜第四章の内容に対応。\n2、段階ボスを倒した後、ランダムな3つの「時の振り子」から1つを選んで獲得できます。\n\n<Title:難易度と初期遺物>\n今回の挑戦には三つの難易度が設定されており、各難易度にはそれぞれ異なるステージ報酬と初期遺物があります。シークレットキーパーは挑戦難易度を選択する前に詳細情報を確認できます。\n\n<Title:ステージ報酬>\n1、各難易度のエリートとボスを倒すことで「VIPポイント」を獲得でき、「VIPポイント」は「優雅室の仕様」レベルを上げて報酬を獲得するために使用します。\n  ·第一段階：エリートを倒す/ボスを倒すで「VIPポイント」×25/75を獲得\n  ·第二段階：エリートを倒す/ボスを倒すで「VIPポイント」×50/150を獲得\n  ·第三段階：エリートを倒す/ボスを倒すで「VIPポイント」×75/225を獲得\n2、挑戦の難易度が高いほど、より多くの「VIPポイント」を獲得できます。\n  ·【難しい難度】：三つの段階を完了して獲得する「VIPポイント」が150%増加\n  ·【狂気の難易度】：三つの段階を完了して獲得する「VIPポイント」が400%増加\n\n<Title:シーズン更新>\n1、「貴賓名簿」は挑戦成績が優秀なシークレットキーパーを記録します。各シーズン中に1回挑戦し、「VIPポイント」を獲得したシークレットキーパーが「貴賓名簿」に入ることができます。\n2、「貴賓名簿」のシーズンランキングは、1回の挑戦で獲得した最多「VIPポイント」と最少「ターン数」を基準とし、繰り返し挑戦してランキングを上げることができます。\n3、シーズン終了後、メールで本シーズンの「貴賓名簿」のランキング報酬が精算されます。\n4、各シーズンにはシーズン任務があり、シーズン任務を完了すると豊富な報酬を獲得できます。シーズン任務は毎回のシーズン更新時にリセットされます。\n5、シーズン切り替え時、まだ戦闘中のステージは挑戦完了後に最新のシーズン任務を直接完了できますが、最新期の「貴賓名簿」には入ることができません。"
  },
