  LanguageConfig_RailWayStageDifficultyBuffContent1_CN = {
    Text = "<Title:ステージ報酬>\n第一段階：エリート/ボスを倒すと「VIPポイント」×25/75を獲得 \n第二段階：エリート/ボスを倒すと「VIPポイント」×50/150を獲得 \n第三段階：エリート/ボスを倒すと「VIPポイント」×75/225を獲得 \n<Title:初期の遺物>\n調査開始時に遺物「小」N「の完全なカメラ」を獲得する\n·<OrangeQuality:ゴールド調和>：「計算力調和」による計算力向上効果は最大1点で、1%のダメージ強化を持つごとに霊識研究深度の効果が1%向上します。\n·<RedQuality:長距離の疲れ>：戦闘中、すべてのライフ回復効果が50％減少します。"
  },
  LanguageConfig_RailWayStageDifficultyBuffContent2_CN = {
    Text = "<Title:ステージ報酬>\n挑戦の難易度が高いほど、より多くの「VIPポイント」を獲得できます。3つのフェーズをクリアすると獲得する「VIPポイント」が150％増加します。\n<Title:初期の遺物>\n調査開始時に遺物「小」N「の古びたカメラ」を獲得します。\n·<OrangeQuality:ゴールド調和>：「行動力調和」による行動力の増加効果は最大1ポイントで、1％のダメージ強化を持つごとに霊識研究深度の効果が1％増加します。\n·<OrangeQuality:次元の贈り物>：探索開始時にランダムで1つの次元影像遺物を獲得し、手札上限が1増加します。\n·<RedQuality:長距離の疲れ>：戦闘中、すべてのライフ回復効果が50％減少します。\n·<RedQuality:眩暈の兆し>：戦闘開始時、すべての覚醒体の現在の狂気とシルバーキーエネルギーが50％減少します。"
