  LanguageConfig_RailWayStageDifficultyBuffContent3V2_CN = {
    Text = "<Title:特別チャレンジ>\n超難度では、第三フェーズ完了後に追加で第四フェーズの最終ボス「タヴィ」に挑戦します。\n<Title:ステージ報酬>\nチャレンジの難易度が高いほど、より多くの「VIPポイント」を獲得できます。3つのフェーズを完了して獲得する「VIPポイント」が 400% 上昇\n最終ボス「タヴィ」を撃破後、追加で「VIPポイント」× 1500 を獲得できます。\n<Title:初期遺物>\n調査開始時に遺物「小」N「の混沌カメラ」を獲得\n·<OrangeQuality:黄金調和>：「計算力調和」による行動力上昇効果の最大値は 1 ポイントで、ダメージ強化を 1% 保有するごとに霊識研究深度の効果が 1% 上昇します。\n·<OrangeQuality:次元の贈物>：探索開始時、ランダムで次元影像遺物を 1 つ獲得し、手札上限が 2 上昇します。\n·<OrangeQuality:祝福された儀式>：第一・第二フェーズのボス撃破報酬がランダムな祝福された遺物 3 択 1 に変更されます。\n·<RedQuality:長距離の疲れ>：戦闘中のすべてのライフ回復効果が 50% 低下します。\n·<RedQuality:眩暈の兆し>：戦闘開始時、すべての覚醒体の現在の狂気とキーエネルギーが 50% 低下します。\n·<RedQuality:永夜の廊下>：探索開始時、すべての覚醒体の基礎狂気とキーエネルギー上限が 50% 上昇します"
  },
  LanguageConfig_RailWayStageDifficultyBuffContent3_CN = {
    Text = "<Title:ステージ報酬>\n挑戦の難易度が高くなるほど、より多くの「VIPポイント」が獲得できます。3つのステージをクリアすることで得られる「VIPポイント」は400%増加します。\n<Title:初期遺物>\n調査開始時に遺物「小「N」の混乱カメラ」を獲得します。\n·<OrangeQuality:黄金調和>：「行動力調和」による行動力の上昇効果は最大1点で、1%のダメージ強化ごとに霊識研究深度の効果が1%増加します。\n·<OrangeQuality:次元の贈り物>：探索開始時、ランダムに1つの次元影像遺物を獲得し、手札上限が2増加します。\n·<OrangeQuality:祝福の儀式>：第一、第二ステージのボスの報酬がランダムな祝福遺物3つから1つに変更されます。\n·<RedQuality:長距離の疲れ>：戦闘中、すべてのライフ回復効果が50%減少します。\n·<RedQuality:眩暈の兆し>：戦闘開始時、すべての覚醒体の現在の狂気とシルバーキーエネルギーが50%減少します。\n·<RedQuality:永夜の廊下>：探索開始時、すべての覚醒体の基本的な狂気とシルバーキーエネルギー上限が50%増加します。"
