  LanguageConfig_Resonance_Group_Desc_1_CN = {
    Text = "【善意の贈り物】で、「無邪気な贈り物」をデッキに追加できる。\n「無邪気な贈り物」：行動力消費1、狂気が最も低い覚醒体に30の狂気を与える。除外。"
  },
  LanguageConfig_Resonance_Group_Desc_24_CN = {
    Text = "事件【狂気の道】で覚醒体1名を指定し、初期の4枚の指令カードを失う。その後、高級遺物3つの中から1つを獲得。\n\n後の4つの事件【精神の破片】で失われた指令カードを順次取り戻すことができる。\n取り戻した指令カードには独自の<EnsembleKeywords:「合奏」>刻印が直接付与される。"
  },
  LanguageConfig_Resonance_Group_Desc_2_CN = {
    Text = "【未完成の蝋人形】で、1枚のカードを選び、その行動力消費を1点減少させる。"
  },
  LanguageConfig_Resonance_Group_Desc_3_CN = {
    Text = "【奇妙な膿】で、「異形の心臓」をデッキに追加できる。行動力消費0、使用後にすべての手札を捨て、捨てた枚数+1のカードを引く。除外。"
  },
  LanguageConfig_Resonance_Group_Desc_4_CN = {
    Text = "【蜂蜜酒】で、「蜂蜜酒」をデッキに追加できる。 —— 行動力消費1、1点の一時的なバリアを獲得。除外。"
  },
  LanguageConfig_Resonance_Group_Desc_5_CN = {
    Text = "「沈みゆく者」およびそれ以降のステージの【代行の儀】で「神国の腕肢」効果を獲得。\n「神国の腕肢」：ターン終了時に前列の敵に自チームの最大ライフの10%のダメージを与える。\n「代行者の裁決」をデッキに追加する。\n「代行者の裁決」：行動力消費0、使用後に現在のライフの10%を失い、「神国の腕肢」が後列の敵に3倍のダメージを与える。ボス戦の場合、10倍のダメージを与える。除外。"
  },
  LanguageConfig_Resonance_Group_Desc_6_CN = {
    Text = "「純白の帆」で、「理想郷の帳」カードをデッキに追加する。行動力消費1点、未装備の3つの「キーオーダー」から、1つを選んで直ちに発動する。「キーオーダー」のクールダウンは発動しない。ボス戦では追加で1回使用可能。除外。"
  },
  LanguageConfig_Resonance_Group_Desc_7_CN = {
    Text = "探索開始付近で、特殊共鳴事件【母なる存在】に遭遇する——\n指令カードを1枚選び、特殊な刻印「生出」を付与するが、ランダムな症状カードが3枚追加される。\n刻印「生出」：カードが保持され、ターン終了時に手札にある場合、保持と除外が付与された未強化コピーを1枚獲得。"
  },
  LanguageConfig_Resonance_Group_Desc_8_CN = {
    Text = "探索開始付近で、特殊共鳴事件【入学式】に遭遇——【極夜の微光】を山札に加える。\n【極夜の微光】：山札か捨て札の山にある指令カードを1枚選択して手札に追加し、その行動力消費を0にする。除外。"
  },
  LanguageConfig_Resonance_Group_Desc_9_CN = {
    Text = "探索開始付近で、特殊な共鳴事件――【入学儀式】に遭遇し、【極夜の微光】をデッキに加える。第8章のすべてのボーナスを引き継ぐ。"
  },
  LanguageConfig_Resonance_Group_Desc_D05EX_CN = {
    Text = "初期遺物「調査隊」を獲得：調査隊の人数30人でスタート。戦闘開始時、「疑念」5枚を山札のランダムな位置に追加。「疑念」：使用時に消費する調査隊の人数を選択し、応じた効果を獲得。\n探索の道中、絶えず「疑念」の決断を迫られ、調査隊員を失っていく。休憩所にたどり着けば救援を受ける機会があり、最終的に無事退避した際、生き残った調査隊の人数に応じて「救難勲章」を獲得する。退避できた人数が多いほど「救難勲章」は強力になる。"
  },
  LanguageConfig_Resonance_Group_Desc_Horla_CN = {
    Text = "探索開始時に初期遺物「オルラのペンとインク」を獲得：戦闘終了後に「ペンとインク」を1点獲得する。「ペンとインク」が2点に達すると消費され、ランダムな「イメージ」を1枚デッキに加える。\n特殊共鳴事件【春の贈り物】で「献詩」を選択可能：3枚の「イメージ」カードを選んで、オルラが「献詩」を作る。"
  },
  LanguageConfig_Resonance_Group_Desc_Lily_CN = {
    Text = "共鳴事件【製作者の迷宮】選択肢「協力者に助けを求める」で上位刻印3つの中から1つを獲得。"
  },
  LanguageConfig_Resonance_Group_Desc_MLYM_CN = {
    Text = "探索開始時に3枚のバフカード<DerivativeCardKeywords_57:「温かい家庭」><DerivativeCardKeywords_58:「誠実な友」><DerivativeCardKeywords_59:「安定した生活」>をデッキに追加する。\n「温かい家庭」：2点の行動力を獲得。\n「誠実な友」：すべての敵に1点の倦怠と軟化を付与する。\n「安定した生活」：カードを2枚引く。"
