  },
  LanguageConfig_Resonance_Group_Desc_Wangda_CN = {
    Text = "共鳴事件「代行の密令」の選択肢「経費を獲得する」で黒章25個とランダムな低級遺物を獲得。"
  },
  LanguageConfig_Resonance_Group_Desc_x1_CN = {
    Text = "共鳴事件【未流出の意識】で、「予備の脳缶」をデッキに追加する。「予備の脳缶」は一度使用したカードを一時的に保存し、状況に応じて取り出して手札に追加することができる。"
