  LanguageConfig_Resonance_Group_Desc_x3_CN = {
    Text = "事件【宴前の儀式】で、「祭霊の夜・特製ブレンド」をデッキに追加できる。\n「祭霊夜・特製ブレンド」：行動力消費1、すべての覚醒体のクリティカル率とクリティカルダメージが一時的に10%増加する。使用後、任意の素材を1つ投入し、その効果をこの戦闘中永続的に付与する！"
