  LanguageConfig_ReturnEventRewardText_CN = {
    Text = "融蝕に対抗する使命は、未知への片道切符であり、罠と危険に満ちている。\n「世界を救う」というテーマは重要であり、迷いやすいものだ。ミサゴ大学の歴史において、多くの若い調査員が使命感に囚われ、理性を失って自らを燃やした。\nだから、あなたが少し休もうと決断したことを、私たちは嬉しく思っている。また守秘者を失うわけにはいかない。\n話はここまでにして、あなたが迅速に調査に戻れるように、リスタートトレーニングプランを用意した。これを行い、結果を持って私のもとに来てくれれば、報酬を用意している。\nちなみに、ラモンナが「小さな贈り物」を用意している。彼女はあなたを恋しく思っている。"
