  LanguageConfig_SchoolTowerChallengeNotReachLevelTips_CN = {
    Text = "挑戦に必要なレベルが不足しています"
  },
  LanguageConfig_SchoolTowerRuleTxt_CN = {
    Text = "<Title:闇の境界>\n・「闇の境界」は高難度の調査ステージです。クリア時に報酬を獲得でき、さらにステージの星評価の累積により、追加報酬も獲得できます。\n\n<Title:調査要件>\n・闇の境界では、特定の界域の覚醒体を使用するよう求められることがあります。詳細は「チーム編成画面」で確認可能です。\n\n<Title:初期遺物>\n・闇の境界には独自の遺物が存在し、効果はそのステージでのみ有効です。遺物効果を効果的に利用すると調査がより効率的になります。"
  },
  LanguageConfig_SchoolTowerTeamBuildFobiddenTips_CN = {
    Text = "現在の選択がチーム要件を満たしていません"
  },
  LanguageConfig_School_Activate_CN = {
    Text = "起動完了"
  },
  LanguageConfig_School_Blood_Content_String_CN = {
    Text = "・ターン開始時に<CardKeyWord:胚胎融合> +20（損失ライフに応じて上昇、最大40）。上限到達時、<CardKeyWord:「胚胎」>を1枚手札に追加。\n・血肉界域の「狂気解放」では<CardKeyWord:「胚胎」>を消費し、<CardKeyWord:捕食>効果を発動して、毎ターン初めての捕食後に最大ライフの2%のシールドと1%の一時的な力を獲得。（損失ライフに応じて最大2倍）"
  },
  LanguageConfig_School_Blood_Title_String_CN = {
    Text = "深紅の犠牲"
  },
  LanguageConfig_School_Chaos_Content_String_CN = {
    Text = "・混沌の覚醒体は界域を越えて編隊可能。\n・混沌の覚醒体が存在するチームは追加で100%の死亡抵抗を獲得。\n・ターン終了後と狂気解放後、<CardKeyWord:キーエネルギー>+50。"
  },
  LanguageConfig_School_Chaos_Title_String_CN = {
    Text = "宇宙の万象"
  },
  LanguageConfig_School_Dimension_Content_String_CN = {
    Text = "・各ターン初めて使用した指令カードは未強化の一時的なコピーが<CardKeyWord:超次元空間>に置かれ、跳躍効果を発動。\n・超次元空間が上限に達した際、1回の超次元ターンを獲得でき、そのターンは通常のドローではなく、超次元空間のカードを手札に追加。跳躍ターンはすべての追加効果を発動できる。"
  },
  LanguageConfig_School_Dimension_Title_String_CN = {
    Text = "次元跳躍"
  },
  LanguageConfig_School_Ocean_Content_String_CN = {
    Text = "・戦闘開始時に1本の触腕を生成し、触腕はターン終了時に前列の敵を攻撃する。\n・狂気解放を1回発動するたびに、ターン終了時に1本の触腕を使って攻撃する。\n・力を3獲得。ごとに触腕ダメージが1増加し、力が3減るごとに触腕ダメージが1減少する。"
