    Text = "一時的なテキスト"
  },
  LanguageConfig_StorylineGuide_1_CN = {
    Text = "危険なレンディニエンの夜霧に足を踏み入れよう、守秘者。あなたの道は、ここから始まる。"
  },
  LanguageConfig_StorylineGuide_20_CN = {
    Text = "一時的なテキスト"
  },
  LanguageConfig_StorylineGuide_2_CN = {
    Text = "アーティスト、狂人、苦行者、愚か者…………この街はあなたのための展示館で、ワックス像たちは物語の始まりの場所に立ち、あなたの訪問を待ち望んでいる。"
  },
  LanguageConfig_StorylineGuide_3_CN = {
    Text = "ライの風雪は殺戮を嫌い、彼女はあなたを待っている、ただ一つの取引のために。彼女はあなたが渇望する秘密をもたらすだろう。彼女の代償は永遠に残酷で、永遠に合理的だ。"
  },
  LanguageConfig_StorylineGuide_4_CN = {
    Text = "思い出せ、思い出のために戦え、思い出のために死ね。思い出は私たちの福音書であり、私たちの墓碑銘である。思い出を除いて、私たちは何も持っていない。"
  },
  LanguageConfig_StorylineGuide_5_CN = {
    Text = "星群が落ちる前に、私たちは海に向かって祈ります：静かな波の音が私たちを夢に導き、故郷の懐に戻り、長い夢から覚めませんように。"
  },
  LanguageConfig_StorylineGuide_6_CN = {
    Text = "歌い上げよ――その古き王は再び彼の玉座を見た。神聖な託宣は、すべての信仰深い民に神の国をもたらす。"
  },
  LanguageConfig_StorylineGuide_7_CN = {
    Text = "聞け、祈り、呼びかけ、繁殖し、最も高貴な理想と最も卑しい欲望に従え。母の名のもとに、彼は混沌と恐怖の中で永遠に存在することができる。"
  },
  LanguageConfig_StorylineGuide_8_CN = {
    Text = "常明の灯が灯り、その幽かな光があなたを終わりへの道を照らします。"
