  LanguageConfig_SummonSelectAwakePanelDesc_CN = {
    Text = "1、運命の選択：守秘者は期間中の運命の選択召喚イベントで覚醒体のリストから1体を選択し、今回の召喚のピックアップ対象とします。\n2、推奨の運命の札：選択した覚醒体の推奨の運命の札が自動的に選択されます！\n3、出現率UP：\n·召喚でSSRを獲得するたびに、33.33％の確率で今期選択したSSR覚醒体または推奨の運命の札となり、覚醒体と推奨の運命の札はUP確率を均等に分け合います。\n·今回の召喚で獲得したSSRがピックアップSSR覚醒体または運命の札ではない場合、次回の召喚で獲得するSSRは必ずピックアップSSR覚醒体または運命の札となります。\n·出現率UP中の内容の内、同じ覚醒体または運命の札を2回連続で取得した場合、次に出現率UP中の内容を取得する際は必ずもう一方の覚醒体または運命の札となります。\n4、覚醒体とその推奨の運命の札を一度選択すると、今回の開催期間中は召喚のピックアップ対象を変更できません。"
