    Text = "<Title:【派遣ルール】>\n・覚醒体を調査任務・研究任務に派遣し、完了後に報酬を獲得できます。\n・各派遣任務には最大4体の覚醒体を派遣可能で、遂行には「派遣総レベル」を満たす必要があります。\n・「派遣総レベル」が必要レベルから追加20毎に、報酬が1つ追加されます。\n・各覚醒体は複数の派遣任務に同時に就かせることはできません。任務途中で派遣をキャンセルすると、覚醒体の枠を即座に解放できますが、報酬は獲得できません。\n・調査レベルが20/30/40/50/60に達すると、追加で派遣任務の枠が1つ増加します。\n・注意：真貌形態の覚醒体は派遣できません。"
