  LanguageConfig_TrinketAutoRefineStopByMaxTimeLimit_CN = {
    Text = "100回の転録が完了しました。自動転録を終了します。"
  },
  LanguageConfig_TrinketAutoRefine_CN = {
    Text = "<Title:自動転写>\n·自動転写は現在の素材状況に応じて、最大 100 回まで転写を行うことができます。\n·自動転写中、転写結果に未ロックの属性強度が 8 のものが 1 つでもあった場合、自動転写は終了します。\n·素材が不足した場合、自動転写は停止します。\n\n<Title:スキップ>\n·自動転写中は各転写結果が表示されます。転写過程をスキップすることを選択できます。スキップ後、自動転写の最終結果が直接表示されます。"
  },
  LanguageConfig_TrinketAutoSelectTips_CN = {
    Text = "自動選択：品質が低く、レベルが低い密契を優先的に素材として選択します"
