  LanguageConfig_TrinketBatchUnbindTitle_CN = {
    Text = "一括析離"
  },
  LanguageConfig_TrinketBindBonusDesc_CN = {
    Text = "結合後、密契のメイン属性が追加で{s1}上昇します！"
  },
  LanguageConfig_TrinketBindNoneSelectedTips_CN = {
    Text = "結合できる密契がありません。少なくとも一つ選択してください。"
  },
  LanguageConfig_TrinketBindRuleDesc_CN = {
    Text = "<Title:密契結合>\n·シークレットキーパーは覚醒体に密契を結合できるようになりました。\n·覚醒体の各スロットに密契を1個結合でき、合計6個まで結合できます。\n·結合後、各スロットの密契のメインステータスが追加で50％上昇します。\n·結合済みの密契は「物資–密契」と「精錬室」には表示されません。\n·編隊と覚醒体助っ人において、覚醒体に密契を装備していない場合、結合済みの密契が自動的に装備されます。\n·結合済みの密契パーツを強化しても結合状態は変わりません。メインステータスの上昇は強化後の状態に応じて更新されます。\n\n<Title:密契析離>\n·密契の結合を変更またはキャンセルするには、密契結合ページで結合済みの密契を析離する必要があります。\n·パーツ1個の析離には、同タイプの密契（スロット不問）を10個消費します。\n·密契を析離する際、使用済みの密契は素材の選択肢に表示されません。"
  },
  LanguageConfig_TrinketBindSuccessTips_CN = {
    Text = "密契の結合に成功しました"
  },
  LanguageConfig_TrinketBind_CN = {Text = "結合"},
  LanguageConfig_TrinketChangeBindSuccessTips_CN = {
    Text = "密契の結合変更に成功しました"
  },
  LanguageConfig_TrinketChangeBind_CN = {Text = "結合"},
  LanguageConfig_TrinketChooseForRecast_CN = {
