  },
  LanguageConfig_TrinketChooseLimited_CN = {
    Text = "選択した密約の数が上限に達しました"
  },
  LanguageConfig_TrinketChoosenSuitTitle_CN = {Text = "セット"},
  LanguageConfig_TrinketChoosenTitle_CN = {
    Text = "密約を選択"
  },
  LanguageConfig_TrinketCompletionRate_CN = {
