  },
  LanguageConfig_TrinketContrast_CN = {Text = "対比"},
  LanguageConfig_TrinketConversionLockOneOption_CN = {
    Text = "「{s1}」を消費して断片を補充"
  },
  LanguageConfig_TrinketConversionNewEnries_CN = {
    Text = "新しいサブ能力"
  },
  LanguageConfig_TrinketConversionOriEnries_CN = {
    Text = "サブ能力"
  },
  LanguageConfig_TrinketConversionReplace_CN = {
    Text = "置き換え"
  },
  LanguageConfig_TrinketConversionRuleTitle_CN = {
    Text = "ルール説明"
  },
  LanguageConfig_TrinketConversionRule_CN = {
    Text = "<Title:転写>\n・転写は密契のサブ属性の種類と数値を変更できますが、メイン能力の種類と数値には影響しません。\n・転写時、サブ能力の種類はメイン能力と重複することができ、サブ能力間の能力タイプも重複することがあります。\n・転写時、サブ能力は異なる強度の数値を獲得します。\n・守秘者が密契転写を解放後、どの方法で新たに獲得した密契も自動的に無料で一度転写されます。\n\n<Title:ロック>\n・転写時、特定のサブ能力を保持したい場合は、サブ能力の横にあるロックボタンをクリックしてロックできます。ロックされたサブ能力の種類と数値は転写時に保持されます。\n・最大で2つのサブ能力を同時にロックできます。\n・1つの能力をロックする場合、追加で対応する「密契の断片」×20を消費します。2つの能力をロックする場合、追加で「追憶の羽ペン」×10を消費します。\n・1つの能力をロックする場合、「追憶の羽ペンで断片を補う」を選択できます。選択すると、現在の「密契の断片」が不足している場合、自動的に対応する数の追憶の羽ペンを消費して転写を行います。"
  },
  LanguageConfig_TrinketConversion_CN = {Text = "転写"},
  LanguageConfig_TrinketCopyRules_CN = {
    Text = "1、禁忌編纂内のステージをクリアし、「密契」を獲得できます！\n2、ステージの推奨レベルごとに、獲得する密契の数が異なります。\n·推奨レベル25のクエストで「密契」×1を獲得できます。\n·推奨レベル35のクエストで「密契」×2を獲得できます。\n·推奨レベル45のクエストで「密契」×3を獲得できます。\n3、ステージチャレンジを完了すると「リプレイ」が解放され、「リプレイ」でそのステージの任務報酬を即座に獲得できます。「リプレイ」では調査で必要な量のエンフェリンを消費します。\n4、各章の「調査」をクリアするごとに、新たに密契ステージが1つ解放されます。\n5、高難易度ステージを星3評価でクリアすると、低難易度のステージの挑戦進捗が自動的に星3評価でクリアしたものとして記録されます。"
  },
