  LanguageConfig_WeekChallengeInstructions_CN = {
    Text = "<Title:【闇の境界】>\n・「闇の境界」は高難度の調査ステージです。守秘者が最終ボスを倒して調査を完了すると、豊富な調査報酬を獲得できます。「闇の境界」の挑戦はエンフェリンを消費しません。\n\n<Title:【挑戦ルール】>\n・守秘者が密境最終ボスを倒して調査を完了すると、対応する星評価を獲得できます。調査スコアの星数が上がるにつれ、異なる報酬を獲得できます。\n・異なる「闇の境界」ステージでは、守秘者は専用の初期遺物サポートを獲得でき、現在の「闇の境界」ステージ内でのみ有効です。\n・1つの「闇の境界」ステージ内で密境ステージをクリアすると、現在の編成で使用した覚醒体が記録されます。同じ覚醒体は他の密境ステージでは使用できません。\n・守秘者はクリア済みの密境ステージの進行をリセットできます。リセットすると、その密境でクリアに使用したキャラクターと星評価の記録が消去され、再編成して挑戦を続けることができます。"
  },
