  LanguageConfig_WeeklyBossInstructions_CN = {
    Text = "\n<Title:報酬受取回数>\n・毎週月曜日の9:00（GMT+8）に報酬受取回数がリセットされます。任意の「超越存在」のステージをクリアすると1回の報酬受取回数を消費して任務報酬が獲得できます。\n・未使用の報酬受取回数は次の週に引き継がれません。\n\n<Title:リプレイ>\n・「超越存在」ステージを初めてクリアするとリプレイが解放されます。リプレイは1回の報酬受取回数を消費して直接任務報酬が獲得できます。\n・高難度ステージを星3でクリアすると、より低い難度のステージの挑戦進捗が自動的に星3クリアとして記録されます。"
